/* hero carousel: the admin's banners first, then slides made from offers that really exist now */
const isHappyHourBanner=b=>b.placement==='happy_hour'||b.link_type==='happy_hour'||
  /^(?:счастливые часы|happy hours?)(?=$|[\s:!—–])/iu.test(String(b.title||'').trim());
const happyCountdown=end=>`<span class="cd"><span aria-hidden="true">${ico('clock',13)}</span><span class="hcd" data-end="${end}">${cdTxt(end-Date.now())}</span></span>`;
function heroSlides(){const out=[],hh=hhStores();
  const top=inB('top'),art=top.find(isHappyHourBanner)||inB('happy_hour')[0];
  for(const b of top){
    if(!isHappyHourBanner(b))out.push({k:'bn',b});
    else if(b===art&&hh.length&&!bannerConfig(b).action)out.push({k:'hap',p:hh[0].p,end:hh[0].end,art:b});
    else if(bannerConfig(b).action)out.push({k:'bn',b});
  }
  const best=STORES.reduce((lead,st)=>TLB.isOpen(st.n)&&st.rd>(lead?.rd||0)?st:lead,null),fr=STORES.filter(x=>TLB.isOpen(x.n)&&(x.ft=='free'||x.ffd||x.fdm>0));
  if(hh.length&&!out.some(x=>x.k==='hap'))out.push({k:'hap',p:hh[0].p,end:hh[0].end,art});if(best)out.push({k:'disc',n:best.rd});if(fr.length)out.push({k:'free',n:fr.length});out.push({k:'brand'});return out}
/* Bento (Home B): the same slides — admin banners first, then real offers. Big tile = first slide (+ the slides after the
   third, swipeable), two small tiles = slides 2 and 3. Fewer than 3 slides → one wide tile. */
function freePlaces(count){
  if(TLB.lang()==='ru')return (count%10===1&&count%100!==11?'в {n} месте рядом':'в {n} местах рядом').replace('{n}',count);
  return count===1?'at 1 place nearby':t('hFreeD').replace('{n}',count);
}
const heroD=x=>({hap:[t('hHhT'),t('hHhD').replace('{n}',x.p),x.end?happyCountdown(x.end):'',t('hHeroGo'),"openHappyHour()",'hamburger'],
  disc:[t('hFlashD').replace('{n}',x.n),t('hHeroT'),'',t('hHeroGo'),"openBannerList('disc')",'hamburger'],free:[t('hFreeT'),freePlaces(x.n),'',t('hFreeGo'),"openBannerList('free')",'motor-scooter'],
  brand:[t('hBrandT'),t('hBrandD'),'',t('hBrandGo'),"openCat('rest')",'pizza']})[x.k];
const bannerCountdown=b=>{
  const cfg=bannerConfig(b),end=bannerDeadline(b);
  return end&&(cfg.action==='campaign'||!cfg.action&&(isDiscountBanner(b)||isFreeDeliveryBanner(b)))?happyCountdown(end):'';
};
function d6Tile(x,cls){if(x.k=='bn')return `<button type="button" class="d6-bt ${x.b.image_url?'img':''} ${cls}" ${bannerAction(x.b)}>${x.b.image_url?`<img src="${esc(x.b.image_url)}" alt="${esc(x.b.title||'')}">`:`<b class="tt">${esc(x.b.title)}</b>`}${bannerCountdown(x.b)}${cls==='d6tm'?`<span class="cta">${esc(bannerLabel(x.b))} ${ico('arr',15)}</span>`:''}</button>`;
  const d=heroD(x);
  if(x.k==='hap'&&x.art?.image_url)return `<button type="button" class="d6-bt img k-hap ${cls}" onclick="${d[4]}"><img src="${esc(x.art.image_url)}" alt=""><b class="tt">${d[0]}</b>${d[2]}</button>`;
  return `<button type="button" class="d6-bt ${cls} k-${x.k}" onclick="${d[4]}"><b class="tt">${d[0]}</b><span class="su">${d[1]}</span>${d[2]}${cls=='d6tm'?`<span class="cta">${d[3]} ${ico('arr',15)}</span>`:`<span class="ar">${ico('arr',18)}</span>`}<img class="art" src="${A3(d[5])}" alt="" width="120" height="120"></button>`}
function heroH(){
  const sl=heroSlides(),happy=sl.find(x=>x.k==='hap'),free=sl.find(x=>x.k==='free');
  let side=sl.length>=3?sl.slice(1,3):[];
  if(happy&&sl.length>=3){
    const companion=free||sl.filter(x=>x!==happy)[1];
    side=[companion,happy];
  }
  const main=sl.filter(x=>!side.includes(x));
  return `<div class="d6-bento ${side.length?'':'one'}"><div class="d6-bm"><div class="d6-bsc" id="hsc" onscroll="heroSync(this)" ontouchstart="HROT.t=Date.now()" onpointerdown="HROT.t=Date.now()">${main.map(x=>d6Tile(x,'d6tm')).join('')}</div>${main.length>1?`<div class="hdt">${main.map((_,i)=>`<i class="${i==HROT.i?'on':''}"></i>`).join('')}</div>`:''}</div>${side.map((x,i)=>d6Tile(x,i?'d6tp':'d6tg')).join('')}</div>`}
const HROT={i:0,t:0};
function heroSync(e){const i=Math.round(e.scrollLeft/Math.max(1,e.clientWidth));if(i!==HROT.i){HROT.i=i;e.parentNode.querySelectorAll('.hdt i').forEach((d,k)=>d.classList.toggle('on',k==i))}}
if(!window.__heroTick)window.__heroTick=setInterval(()=>{const e=$('hsc');if(!e||S.v!='home'||document.hidden||Date.now()-HROT.t<8000||(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches))return;const n=e.children.length;if(n<2)return;const i=(HROT.i+1)%n;e.scrollTo({left:i*e.clientWidth,behavior:'smooth'})},5000);

