#app .d6h .home-dine .d6-dc .d6-ph { width:100%; height:146px; border-radius:16px; }
#app .d6h .home-dine .dine-brand-cover .dish-store-logo { position:absolute; top:auto; bottom:8px; right:auto; left:8px; width:42px; height:42px; border-radius:11px; border:1px solid #fff; z-index:5; background:#fff; box-shadow:0 2px 6px #0005; }
#app .d6h .home-dine .dine-brand-cover .hb { position:absolute; top:9px; left:9px; right:auto; bottom:auto; z-index:5; width:max-content; max-width:calc(100% - 76px); white-space:nowrap; overflow:visible; border-radius:9px; padding:4px 8px; line-height:16px; font-size:12px; }
#app .d6h .home-dine .d6-dc .nm { display:block; margin:8px 2px 3px; min-height:0; color:var(--ink); font-size:14px; line-height:19px; font-weight:700; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
#app .d6h .home-dine .d6-dc .dine-meta { display:block; margin:0 2px 1px; min-height:18px; white-space:nowrap; }
#app .d6h .home-dine .d6-dc .dine-meta .rt { display:inline-flex; align-items:center; color:var(--ink); font-weight:600; font-size:12px; }
#app .d6h .home-dine .d6-dc .dine-bill-distance { display:block; margin:0 2px; color:var(--mut2); font-size:12px; line-height:18px; white-space:normal; overflow-wrap:break-word; }

/* BRIEF-25c Y-08: sibling control surface avoids nested buttons; optional stats only. */
.home-discover .reel-tile{position:relative;flex:0 0 calc((100% - 12px)/2.5);height:192px;min-width:0;scroll-snap-align:start;}
.home-discover .reel-tile>.reel-card.discover-row{width:100%;height:100%;flex:none;scroll-snap-align:unset;}
.home-discover .reel-tile.has-feedback .reel-copy{bottom:43px;}
.home-discover .reel-feedback[hidden]{display:none!important;}
.home-discover .reel-feedback{position:absolute;z-index:4;left:6px;bottom:6px;display:inline-flex;align-items:center;gap:1px;max-width:calc(100% - 12px);min-height:31px;box-sizing:border-box;padding:2px 4px;border:1px solid #ffffff52;border-radius:999px;background:#171b24bb;backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);color:#fff;}
.home-discover .reel-feedback button{display:inline-flex;align-items:center;justify-content:center;gap:3px;min-width:31px;min-height:27px;padding:2px 4px;border:0;border-radius:999px;background:transparent;color:#fff;font:600 11px/15px -apple-system,BlinkMacSystemFont,sans-serif;cursor:pointer;}
.home-discover .reel-feedback button.on{background:#ed551c;color:#fff;}
.home-discover .reel-feedback button:focus-visible{outline:2px solid white;outline-offset:1px;}
.home-discover .reel-feedback button:disabled{opacity:.6;cursor:default;}
.home-discover .reel-feedback button svg{flex:none;}
.home-discover .reel-feedback-separator{height:18px;width:1px;flex:none;background:#ffffff70;}

/* BRIEF-27: side banners fill their tiles even when the source is smaller. */
#app .d6h .d6-bento > .d6-bt.img > img {
  position: absolute; inset: 0; width: 100%; height: 100%;
  object-fit: cover; object-position: left center;
}

/* Happy-hour countdown remains legible on both kinds of artwork. */
#app .d6h .d6-bt.k-hap .cd { flex: none; width: max-content; background: #fff; color: #37251e; }
#app .d6h .d6-bt.k-hap .cd > span:first-child { display: inline-flex; }
#app .d6h .d6-bt.k-hap.img > img { position: absolute; inset: 0; object-fit: cover; }
#app .d6h .d6-bt.k-hap.img::after {
  content: ''; position: absolute; inset: 0; background: linear-gradient(#1a100dcc, transparent 70%);
  pointer-events: none;
}
#app .d6h .d6-bt.k-hap.img .tt { color: #fff; padding: 8px 10px 0; font-size: 14px; line-height: 17px; }
#app .d6h .d6-bt.k-hap.img .cd { position: absolute; bottom: 8px; left: 10px; }

/* Keep the main carousel indicators over the image and clear of its CTA. */
#app .d6h .d6-bm { overflow: hidden; }
@media (max-width: 430px) {
  #app .d6h .d6-bento:not(.one) { grid-template-rows: repeat(2, minmax(82px, 1fr)); }
}
#app .d6h .d6-bsc > .d6-bt:not(.img) { padding-bottom: 12px; }
#app .d6h .d6-bm:has(.hdt) .d6-bsc > .d6-bt:not(.img) { padding-bottom: 32px; }
#app .d6h .d6-bm .hdt {
  z-index: 2; inset: auto 12px 12px auto; padding: 4px 7px;
  border-radius: 999px; background: rgb(255 255 255 / 82%);
}
#app .d6h .d6-bm .hdt i { background: #ed551c66; }
#app .d6h .d6-bm .hdt i.on { background: #ed551c; }
#app .d6h .home-ad-carousel { position: relative; }
#app .d6h .home-ad-dots {
  position: absolute; z-index: 2; inset: auto 12px 12px auto; padding: 4px 7px;
  border-radius: 999px; background: rgb(255 255 255 / 82%); pointer-events: none;
}
#app .d6h .home-ad-dots i { background: #ed551c66; }
#app .d6h .home-ad-dots i.on { background: #ed551c; }

#app .d6h button.d6-bt { border: 0; font: inherit; text-align: start; }

/* BRIEF-26: Happy Hours sheet. */
.hh-sheet {
  position: fixed; inset: auto 0 0; margin: 0 auto; width: min(100%, 540px); max-width: 100%;
  height: 90dvh; max-height: 90dvh; padding: 0; border: 0; border-radius: 24px 24px 0 0;
  overflow: hidden; color: #29211e; background: #fff;
}
.hh-sheet[open] { display: flex; flex-direction: column; }
.hh-sheet::backdrop { background: #21181282; }
.hh-sheet-hero {
  position: relative; isolation: isolate; flex: none; text-align: center;
  padding: 18px 50px 26px; background: #f7f0e6; border-radius: 0 0 50% 7% / 0 0 10% 3%;
}
.hh-sheet-hero::after {
  content: ''; position: absolute; z-index: -1; inset: auto 0 -8px; height: 23px;
  background: inherit; border-radius: 52% 0 65% 28%;
}
.hh-sheet-close {
  position: absolute; top: 12px; right: 12px; display: grid; place-items: center;
  width: 42px; height: 42px; border: 0; border-radius: 50%; color: #42322a; background: #fff;
}
.hh-sheet-clock {
  display: grid; place-items: center; width: 58px; height: 58px; margin: 0 auto 9px;
  border: 2px solid #e89d3e; border-radius: 50%; color: #97511b;
  background: radial-gradient(circle at 34% 23%, #fffdfa, #ffd88d 70%, #ec9f49);
  box-shadow: inset 0 2px 3px #fff9, 0 4px 0 #a75e26, 0 7px 12px #6a321b39;
}
.hh-sheet-hero h2 { margin: 9px 0 7px; font-size: clamp(22px, 7vw, 34px); line-height: 1.1; }
.hh-sheet-ribbon {
  display: table; margin: 0 auto 12px; padding: 3px 14px; border-radius: 6px;
  transform: rotate(-4deg); font-size: 18px; background: #332316; color: #dcfaac;
}
.hh-sheet-hero .cd {
  display: inline-flex; align-items: center; gap: 5px; padding: 4px 10px; border-radius: 999px;
  background: #fff; font-weight: 700; font-variant-numeric: tabular-nums;
}
.hh-sheet-hero .cd > span:first-child { display: inline-flex; }
.hh-sheet-hero p { margin: 5px 0 0; color: #6b5849; font-size: 12px; }
.hh-sheet-list { overflow-y: auto; overscroll-behavior: contain; padding: 15px 16px max(12px, env(safe-area-inset-bottom)); }
.hh-sheet-store {
  display: flex; align-items: center; gap: 12px; width: 100%; min-height: 110px; padding: 10px 0;
  border: 0; border-bottom: 1px solid #ede8e3; background: #fff; color: inherit; font: inherit; text-align: start;
}
.hh-sheet-store.closed { color: #6f6a65; filter: grayscale(1); opacity: .68; }
.hh-sheet-photo {
  position: relative; flex: 0 0 92px; height: 92px; overflow: hidden; border-radius: 16px;
  background: #eee5dc;
}
.hh-sheet-photo > img { width: 100%; height: 100%; object-fit: cover; }
.hh-sheet-photo .dish-store-logo {
  position: absolute; top: auto; left: 6px; bottom: 6px; width: 32px; height: 32px; border-radius: 8px;
}
.hh-sheet-copy { flex: 1; min-width: 0; display: grid; justify-items: start; gap: 3px; }
.hh-sheet-copy > b:first-child { font-size: 16px; overflow-wrap: anywhere; }
.hh-sheet-copy .rt { display: inline-flex; align-items: center; gap: 3px; font-size: 13px; }
.hh-sheet-copy .rt .i { color: #e99b26; }
.hh-sheet-copy .rt i { font-style: normal; }
.hh-sheet-meta { color: #665b54; font-size: 12px; }
.hh-sheet-deal { padding: 2px 7px; border-radius: 7px; color: #273b13; background: #e0f4bd; font-size: 12px; font-weight: 700; }

/* Configured hero artwork and its own call to action share a single accessible control. */
#app .d6h .d6-bsc > .d6-bt.img .cta {
  position: absolute; bottom: 10px; left: 10px; right: auto; max-width: calc(100% - 20px);
  text-align: start;
}
#app .d6h .d6-bm:has(.hdt) .d6-bsc > .d6-bt.img .cta { bottom: 32px; }

#app .d6h .d6-bt.img .cd {
  display: inline-flex; align-items: center; position: absolute; top: 8px; left: 8px;
  background: #fff; color: #37251e;
}
#app .d6h .d6-bt.k-hap.img .cd { top: auto; }
